# SCRIPT: SM-SU3-CONE-01
# ITEM 0. Lie algebra generated by the tree's own moves. Boost generators K_i (4x4), and the turns between arms
#   (commutators of boosts are rotations). KILL for "reading B gets the SU(3) gluon algebra": the closure is not 8-dimensional / not su(3).
#   Also checked exactly: the six arms seen down (1,1,1) are the SU(3) 3+3bar weights; the arm permutations by the Hurwitz unit (1+i+j+k)/2 and a swap give S3 = Weyl group of SU(3).
# ITEM 2. Exact count of tree nodes (Garrett ratio 5, depth <= 7) on the Koide cone 2(x+y+z)^2 = 3(x^2+y^2+z^2), integers over 5^n.
#   KILL for "the 45-degree cone about (1,1,1) is in the tree itself": zero exact hits AND cos^2 = 1/2 is not singled out (count in a window around 1/2 not above neighbouring windows).
import numpy as np, itertools, math
from fractions import Fraction
def K(i):
    M = np.zeros((4,4)); M[0,i+1] = M[i+1,0] = 1; return M
def closure(gens):
    basis = []
    def add(M):
        v = M.flatten()
        if not basis: 
            if np.linalg.norm(v) > 1e-9: basis.append(v); return True
            return False
        A = np.array(basis); r0 = np.linalg.matrix_rank(A, 1e-9); r1 = np.linalg.matrix_rank(np.vstack([A, v]), 1e-9)
        if r1 > r0: basis.append(v); return True
        return False
    work = [g for g in gens if add(g)]
    changed = True
    while changed:
        changed = False; cur = [b.reshape(4,4) for b in basis]
        for X, Y in itertools.combinations(cur, 2):
            if add(X@Y - Y@X): changed = True
    return len(basis)
d = closure([K(0), K(1), K(2)])
print(f"ITEM 0: Lie algebra generated by the three arm boosts: dimension {d} (so(3,1) = sl(2,C) has 6; su(3) has 8) ->", "KILL FIRED (weights only)" if d != 8 else "survives")
Jt = [K(0)@K(1)-K(1)@K(0), K(1)@K(2)-K(2)@K(1), K(2)@K(0)-K(0)@K(2)]
print(f"        turns between arms ([K_i,K_j]) close on dimension {closure(Jt)} (rotations so(3) = su(2): 3)")
# weights: projections of +-e_a onto the plane perpendicular to (1,1,1)
D = np.ones(3)/math.sqrt(3); P = [s*np.eye(3)[a] - (s*np.eye(3)[a]@D)*D for a in range(3) for s in (1,-1)]
ang = sorted(round(math.degrees(math.atan2(p@np.array([0,1,-1])/math.sqrt(2), p@np.array([2,-1,-1])/math.sqrt(6))) % 360, 6) for p in P)
print("        six arms seen down (1,1,1): angles", ang, " lengths", sorted({round(float(np.linalg.norm(p)),9) for p in P}), "(regular hexagon = SU(3) 3+3bar weights)")
# Weyl group: conjugation by q=(1+i+j+k)/2 cycles i->j->k; a swap (by (j-k)/sqrt2, also an octahedral unit) exchanges j,k
def qmul(a,b):
    a0,a1,a2,a3=a; b0,b1,b2,b3=b
    return (a0*b0-a1*b1-a2*b2-a3*b3, a0*b1+a1*b0+a2*b3-a3*b2, a0*b2-a1*b3+a2*b0+a3*b1, a0*b3+a1*b2-a2*b1+a3*b0)
def conj(q,v): qi=(q[0],-q[1],-q[2],-q[3]); n=sum(x*x for x in q); r=qmul(qmul(q,(0,)+v),qi); return tuple(round(x/n,9) for x in r[1:])
q=(0.5,0.5,0.5,0.5); s=(0,0,1/math.sqrt(2),-1/math.sqrt(2)) 
print("        (1+i+j+k)/2 sends i,j,k to", [conj(q,v) for v in [(1,0,0),(0,1,0),(0,0,1)]], "; (j-k)/sqrt2 sends i,j,k to", [conj(s,v) for v in [(1,0,0),(0,1,0),(0,0,1)]])
# ITEM 2: exact integer nodes
def B(ax, sg):
    M = [[5 if i==j else 0 for j in range(4)] for i in range(4)]; M[0][0] = 13; M[ax+1][ax+1] = 13; M[0][ax+1] = M[ax+1][0] = 12*sg; return M
def apply(M, v): return [sum(M[i][k]*v[k] for k in range(4)) for i in range(4)]
GEN = [B(a, s) for a in range(3) for s in (1,-1)]
nodes = []; frontier = [((1,0,0,0), -1)]
for depth in range(1, 8):
    nf = []
    for v, last in frontier:
        for g in range(6):
            if last >= 0 and g == (last ^ 1): continue
            w = apply(GEN[g], v); nf.append((tuple(w), g)); nodes.append((w, depth))
    frontier = nf
hits = []; c2 = []
for w, dep in nodes:
    x, y, z = w[1], w[2], w[3]
    if 2*(x+y+z)**2 == 3*(x*x+y*y+z*z): hits.append((dep, w))
    c2.append((x+y+z)**2/(3*(x*x+y*y+z*z)))
c2 = np.array(c2); win = lambda a, h=0.005: int(np.sum(np.abs(c2 - a) < h))
print(f"ITEM 2: {len(nodes)} tree nodes to depth 7; exact hits on the Koide cone cos^2 = 1/2: {len(hits)}" + (f"  first: {hits[:3]}" if hits else ""))
print("        nodes within 0.005 of cos^2 = 0.40, 0.45, 0.50, 0.55, 0.60:", [win(a) for a in (0.40,0.45,0.50,0.55,0.60)], "; special values 1/3 (on an arm):", win(1/3, 1e-12), " 1 (on the diagonal):", win(1.0, 1e-12))
v = 'KILL FIRED' if (len(hits) == 0 and win(0.5) <= max(win(0.45), win(0.55))) else 'survives'
print("        ->", v)
